import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Cart","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/cart/index.md","filePath":"api/rest-api/shop/cart/index.md","lastUpdated":1787725411000}'),d={name:"api/rest-api/shop/cart/index.md"};function c(i,e,s,n,h,p){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="cart" tabindex="-1">Cart <a class="header-anchor" href="#cart" aria-label="Permalink to &quot;Cart&quot;">​</a></h1><p>The Cart menu is the shopping basket: create a cart, add and update items, remove items, and apply or remove a coupon. Every response returns the up-to-date cart with its items and recalculated totals, so a client never needs a separate refresh call after a change.</p><h2 id="the-cart-token" tabindex="-1">The cart token <a class="header-anchor" href="#the-cart-token" aria-label="Permalink to &quot;The cart token&quot;">​</a></h2><p>A cart is identified by a <strong>cart token</strong>. Create a cart to obtain it, then send it as <code>Authorization: Bearer &lt;cartToken&gt;</code> on every subsequent cart request (and into checkout). The cart token works for both guests and logged-in customers — guests can build a cart without an account, and the same token carries the cart through checkout.</p><h2 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h2><p>Apply a coupon code to discount the cart, or remove it to revert. The cart totals in the response reflect the coupon immediately.</p><h2 id="merging-a-guest-cart" tabindex="-1">Merging a guest cart <a class="header-anchor" href="#merging-a-guest-cart" aria-label="Permalink to &quot;Merging a guest cart&quot;">​</a></h2><p>When a shopper builds a cart as a guest and then logs in, merge the guest cart into their customer cart so nothing is lost. Call <a href="/api/rest-api/shop/cart/merge-cart.html">Merge Cart</a> with the <strong>customer</strong> Bearer token and the guest cart&#39;s <code>cart_id</code>: items with the same product and type have their quantities added, other items are copied over, the guest cart is deactivated, and the response is the up-to-date customer cart. Merge requires an authenticated customer (<code>401</code> for a guest) and a valid guest cart id (<code>404</code> otherwise).</p><h2 id="body-field-names-differ-per-call" tabindex="-1">Body Field Names Differ Per Call <a class="header-anchor" href="#body-field-names-differ-per-call" aria-label="Permalink to &quot;Body Field Names Differ Per Call&quot;">​</a></h2><p>The cart endpoints do not share one naming convention, and sending the wrong key is read as a missing value rather than an error about the key:</p><table tabindex="0"><thead><tr><th>Call</th><th>Field</th><th>Not</th></tr></thead><tbody><tr><td>Add to cart</td><td><code>productId</code>, <code>quantity</code></td><td>—</td></tr><tr><td>Update item</td><td><code>cartItemId</code> <strong>and</strong> <code>quantity</code>, both required</td><td>quantity <code>0</code> is rejected; use Remove instead</td></tr><tr><td>Remove one item</td><td><code>cartItemId</code></td><td><code>itemIds</code></td></tr><tr><td>Remove several items</td><td><code>itemIds</code> (array)</td><td><code>cartItemId</code></td></tr><tr><td>Apply coupon</td><td><code>couponCode</code></td><td><code>code</code></td></tr></tbody></table><p>The item id in all of these is the <strong>cart line</strong> id from <code>items[].id</code>, never the product id. An unknown line id on Update answers <code>201</code> with <code>success: true</code> and changes nothing, so confirm the change by reading <code>items</code> back rather than trusting the flag.</p><h2 id="what-comes-back" tabindex="-1">What Comes Back <a class="header-anchor" href="#what-comes-back" aria-label="Permalink to &quot;What Comes Back&quot;">​</a></h2><p>Every call returns the whole recalculated cart: <code>items</code> with per-line prices and totals, the <code>subtotal</code> / <code>taxAmount</code> / <code>shippingAmount</code> / <code>grandTotal</code> family with <code>formatted*</code> twins, the applied <code>couponCode</code>, and the checkout fields (<code>billingAddress</code>, <code>shippingAddress</code>, <code>paymentMethod</code>, <code>selectedShippingRate</code>) that fill in during checkout. Writes add <code>success</code> and <code>message</code> on top.</p><p>Because the payload is the full cart, re-render from the response — a follow-up read is never needed after a write.</p><h2 id="empty-carts-and-failed-writes" tabindex="-1">Empty Carts and Failed Writes <a class="header-anchor" href="#empty-carts-and-failed-writes" aria-label="Permalink to &quot;Empty Carts and Failed Writes&quot;">​</a></h2><p>Removing the last line leaves an <strong>empty cart</strong>, not a deleted one: the same <code>cartToken</code> keeps working and the shopper can carry on adding. A failed coupon is the one case where <code>success</code> matters — a wrong or non-qualifying code still answers <code>201</code> with the cart untouched, so branch on <code>success</code>, not on the status code.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><p>Every cart write is a <strong>POST</strong>. There is no <code>GET</code>, <code>PUT</code>, or <code>DELETE</code> on this surface — reading the cart is a POST too, because the cart is identified by the token in the <code>Authorization</code> header rather than by a path parameter.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a></td><td><code>POST /api/shop/cart-tokens</code></td><td>Start a cart and receive its token.</td></tr><tr><td><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a></td><td><code>POST /api/shop/cart</code></td><td>Read the cart with its items and totals.</td></tr><tr><td><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a></td><td><code>POST /api/shop/add-product-in-cart</code></td><td>Add a product of any type.</td></tr><tr><td><a href="/api/rest-api/shop/cart/update-cart-item.html">Update Cart Item</a></td><td><code>POST /api/shop/update-cart-item</code></td><td>Change an item&#39;s quantity.</td></tr><tr><td><a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a></td><td><code>POST /api/shop/remove-cart-item</code></td><td>Remove one item.</td></tr><tr><td><a href="/api/rest-api/shop/cart/upload-customizable-file.html">Upload Customizable File</a></td><td><code>POST /api/shop/customizable-option-files</code></td><td>Attach a file to a customizable option.</td></tr><tr><td><a href="/api/rest-api/shop/cart/apply-coupon.html">Apply Coupon</a></td><td><code>POST /api/shop/apply-coupon</code></td><td>Apply a coupon code.</td></tr><tr><td><a href="/api/rest-api/shop/cart/remove-coupon.html">Remove Coupon</a></td><td><code>POST /api/shop/remove-coupon</code></td><td>Remove the applied coupon.</td></tr><tr><td><a href="/api/rest-api/shop/cart/merge-cart.html">Merge Cart</a></td><td><code>POST /api/shop/merge-carts</code></td><td>Merge a guest cart into the customer&#39;s cart after login.</td></tr></tbody></table><p>There is also <code>POST /api/shop/remove-cart-items</code>, which takes an <code>itemIds</code> list and removes several lines in one call.</p><p>Every one of these returns the <strong>updated cart</strong> as a bare object, so a client can re-render from the response without a follow-up read.</p><p>All Cart endpoints require the storefront key and a cart token (issued by Create Cart) — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',23)]))}const m=t(d,[["render",c]]);export{u as __pageData,m as default};
